__device__ unsigned tf_ds_block_argmax_v(const float* row, int n, float* out_v);

// TF_DS_PDL: wait for the kernel this one follows (its memory flushed), then let the next one launch (programmatic
// dependent launches, sm_90+). Every kernel in this file takes `pdl` as its last argument (0: same instruction stream as
// before); the l2 prefetch kernel is the one exception: it reads the NEXT kernels' weights into L2 and must not run
// mid-flight against its predecessor's working set, so it neither takes `pdl` nor is launched with the attribute.
__device__ __forceinline__ void pdl_enter(int pdl) {
#if defined(__CUDA_ARCH__) && __CUDA_ARCH__ >= 900
    if (pdl) {
        asm volatile("griddepcontrol.wait;" ::: "memory");
        asm volatile("griddepcontrol.launch_dependents;" ::: "memory");
    }
#endif
}

// `.float()` of fp16 values (exact): the MoE gate's weights before torch's fp32 GEMM (model.py moe, prompt rows).
extern "C" __global__ void tf_ds_f16_to_f32_kernel(const __half* input, float* output, uint64_t count, int pdl) {
    pdl_enter(pdl);
    for (uint64_t i = uint64_t(blockIdx.x) * blockDim.x + threadIdx.x; i < count;
         i += uint64_t(gridDim.x) * blockDim.x) output[i] = __half2float(input[i]);
}

// Comm.sum of two ranks' fp32 partials, then `.to(bf16)`: acc = g0 + g1 (one fp32 add, rank order), rounded to nearest
// even into bf16 (model.py engram_apply: comm.sum(mm(engram_wkv, e, F32)).to(BF16)).
extern "C" __global__ void tf_ds_add2_bf16_kernel(const float* g0, const float* g1, __nv_bfloat16* output,
                                                  uint64_t count, int pdl) {
    pdl_enter(pdl);
    for (uint64_t i = uint64_t(blockIdx.x) * blockDim.x + threadIdx.x; i < count;
         i += uint64_t(gridDim.x) * blockDim.x) output[i] = __float2bfloat16_rn(__fadd_rn(g0[i], g1[i]));
}

// A profile's GPU clock (ns, %globaltimer) when the stream reaches it, appended with its tag: buf[0] the count (reset
// first when `reset`), then (clock, tag) pairs, at most `cap` (round phase timing; in a graph like any kernel).
extern "C" __global__ void tf_ds_clock_kernel(uint64_t* buf, uint32_t tag, uint32_t reset, uint32_t cap, int pdl) {
    pdl_enter(pdl);
    if (threadIdx.x == 0) {
        uint64_t t;
        asm volatile("mov.u64 %0, %%globaltimer;" : "=l"(t));
        const uint64_t i = reset ? 0 : buf[0];
        if (i < cap) {
            buf[1 + 2 * i] = t;
            buf[2 + 2 * i] = tag;
            buf[0] = i + 1;
        }
    }
}

