//! TF_DS_MARKOV_FUSED (off by default): a greedy draft step's Markov bias miss rows and its tile scoring in one
//! launch (tf_ds_markov_fused_kernel, dsv41_ops.cu) instead of the kit's _bias then _score. Pure: no cuda import; the
//! launcher is Ops.markovFused and the call site is draft.zig's Markov loop (tri_markov.Markov.stepsFused). A malformed
//! switch refuses startup.
//!
//! On a cache miss _bias computes the step's bias row, rounds it to fp16 into the staging rows and _score rereads it:
//! 64,640 staged fp16 values per missed stream, step and rank (252.5 KiB of write and reread at the served 129,280
//! vocabulary on TP2). The fused kernel computes the miss rows' bias and adds the logits without staging: the round to
//! fp16 stays (the drafts are bit-identical), the staging rows are not written (greedy steps have no later reader of
//! them; a step that may be sampled keeps the old path and its staged bias for the sampled hook).
const std = @import("std");

pub const env_name: [:0]const u8 = "TF_DS_MARKOV_FUSED";

/// The switch's value: unset, "" or "0" off; "1" on; anything else is a refusal to start (the message is on stderr).
pub fn parse(text: ?[]const u8) ?bool {
    const t = text orelse return false;
    if (t.len == 0 or std.mem.eql(u8, t, "0")) return false;
    if (std.mem.eql(u8, t, "1")) return true;
    std.debug.print("{s}: expected 1 or 0\n", .{env_name});
    return null;
}

pub fn fromText(text: ?[]const u8) error{BadMarkovFused}!bool {
    return parse(text) orelse error.BadMarkovFused;
}

/// Whether the fused launch supports this step's shapes (the call sites fall back to _bias + _score when it does not):
/// rows at the kernel's 16 (markov.NP), and the ids and partials the kernel keeps in 32-bit fields below its BIG
/// sentinel (1 << 30, _score's masked index).
pub fn fuseOk(fused: bool, rows: usize, cols: usize, segs: usize, seg0: usize, rank: usize, n_part: usize) bool {
    return fused and rows >= 1 and rows <= 16 and cols >= 1 and segs >= 1 and rank >= 1 and n_part >= 1 and
        cols <= std.math.maxInt(c_int) and n_part <= std.math.maxInt(c_int) and
        (seg0 + segs) * cols <= (1 << 30);
}

// -- host reference (the kit's markov.py semantics: _bias, _score, _finish) ------------------------------------------

/// markov.py's _better: (v1, i1) before (v2, i2) in torch.argmax's order: NaN above everything, then the larger
/// value, ties (and NaN against NaN) to the lower index.
pub fn better(v1: f32, i1: i32, v2: f32, i2: i32) bool {
    const n1 = v1 != v1;
    const n2 = v2 != v2;
    const gt = (v1 > v2) or ((v1 == v2) and (i1 < i2));
    return (n1 and (!n2 or i1 < i2)) or (!n1 and !n2 and gt);
}

/// bf16 bits widened to fp32 (`.float()`, exact).
pub fn widen(b: u16) f32 {
    return @bitCast(@as(u32, b) << 16);
}

/// fp32 rounded to fp16 bits (round to nearest even).
pub fn round16(x: f32) u16 {
    return @bitCast(@as(f16, x));
}

/// fp16 bits widened to fp32 (exact).
pub fn widen16(h: u16) f32 {
    return @as(f32, @as(f16, @bitCast(h)));
}

/// _bias's element: fp16(head[v] . fp16(emb[tok])) — the fp32 dot in rank order (fp16 x fp16 products are exact),
/// rounded to fp16. `head` is the column's row of the head (fp16 bits), `emb` the token's row of the embedding (bf16).
pub fn biasElem(head: []const u16, emb: []const u16) u16 {
    std.debug.assert(head.len == emb.len);
    var acc: f32 = 0;
    for (head, emb) |w, e| acc += widen16(w) * roundTo16Back(e);
    return round16(acc);
}

/// _bias's embedding step: the bf16 element rounded to fp16 (`e = e.to(tl.float16)`).
fn roundTo16Back(e: u16) f32 {
    return widen16(round16(widen(e)));
}

/// One step's per-tile winners and draft id for `n` rows: for each row the bias is its cached row (`cache` rows of
/// `cols` fp16, `slot[row] >= 0`) or, on a miss, `biasElem` over the row's token embedding (bf16 `rank` values) and
/// each column's head row (fp16 `rank` values, column v at `head[v * rank ..]`); widened, plus the logit (row r at
/// `lg[r * cols ..]`); each tile of `bc` columns emits its best (value, id = `seg0 * cols + c`) under `better` into
/// `tiles`, and the returned id is the best of the tiles' (like _finish). `tiles` is [n, ceil(cols / bc)].
pub fn step(n: usize, cols: usize, bc: usize, rank: usize, seg0: usize, lg: []const f32, slot: []const i32, tok: []const i64, cache: []const u16, emb: []const u16, head: []const u16, tiles: []f32, ids: []i32) i64 {
    const s_tiles = (cols + bc - 1) / bc;
    std.debug.assert(lg.len >= n * cols and slot.len > 0 and tok.len >= n and cache.len >= slot.len * cols or cache.len == 0);
    std.debug.assert(emb.len >= maxTok(tok) * rank + rank and head.len >= (seg0 + 1) * cols * rank);
    std.debug.assert(tiles.len >= n * s_tiles and ids.len >= n * s_tiles);
    for (0..n) |r| {
        const at = slot[@intCast(tok[r])];
        for (0..s_tiles) |t| {
            var bv: f32 = -std.math.inf(f32);
            var bi: i32 = 1 << 30;
            const c0 = t * bc;
            const c1 = @min(c0 + bc, cols);
            for (c0..c1) |c| {
                const bias: u16 = if (at >= 0)
                    cache[@as(usize, @intCast(at)) * cols + c]
                else
                    biasElem(head[c * rank ..][0..rank], emb[@as(usize, @intCast(tok[r])) * rank ..][0..rank]);
                const sc = lg[r * cols + c] + widen16(bias);
                const v: i32 = @intCast(seg0 * cols + c);
                if (better(sc, v, bv, bi)) {
                    bv = sc;
                    bi = v;
                }
            }
            tiles[r * s_tiles + t] = bv;
            ids[r * s_tiles + t] = bi;
        }
    }
    var out: i64 = -1;
    for (0..n) |r| {
        var bv: f32 = -std.math.inf(f32);
        var bi: i32 = 1 << 30;
        for (0..s_tiles) |t| if (better(tiles[r * s_tiles + t], ids[r * s_tiles + t], bv, bi)) {
            bv = tiles[r * s_tiles + t];
            bi = ids[r * s_tiles + t];
        };
        out = bi;
    }
    return out;
}

fn maxTok(tok: []const i64) usize {
    var m: usize = 0;
    for (tok) |t| m = @max(m, @intCast(t));
    return m;
}

// -- tests ----------------------------------------------------------------------------------------------------------

const expectEqual = std.testing.expectEqual;

test "the switch parses its forms and nothing else" {
    try expectEqual(false, parse(null).?);
    try expectEqual(false, parse("").?);
    try expectEqual(false, parse("0").?);
    try expectEqual(true, parse("1").?);
    try expectEqual(@as(?bool, null), parse("2"));
    try expectEqual(@as(?bool, null), parse("on"));
    try expectEqual(@as(?bool, null), parse("01"));
    try std.testing.expectEqual(@as(bool, true), try fromText("1"));
    try std.testing.expectError(error.BadMarkovFused, fromText("2"));
}

test "fuseOk takes the step's bounds" {
    try std.testing.expect(fuseOk(true, 1, 64640, 1, 1, 256, 64));
    try std.testing.expect(fuseOk(true, 16, 128, 2, 0, 1, 1));
    try std.testing.expect(!fuseOk(false, 1, 64640, 1, 1, 256, 64));
    try std.testing.expect(!fuseOk(true, 0, 64640, 1, 1, 256, 64));
    try std.testing.expect(!fuseOk(true, 17, 64640, 1, 1, 256, 64));
    try std.testing.expect(!fuseOk(true, 4, 0, 1, 1, 256, 64));
    try std.testing.expect(!fuseOk(true, 4, 64640, 1, 1, 0, 64));
    try std.testing.expect(!fuseOk(true, 4, 64640, 1, 1, 256, 0));
    // the ids stay below the masked column's sentinel (1 << 30)
    try std.testing.expect(fuseOk(true, 4, 1 << 29, 1, 0, 256, 64));
    try std.testing.expect(!fuseOk(true, 4, 1 << 29, 1, 1, 256, 64));
}

test "better is torch.argmax's order: NaN above everything, ties to the lower index" {
    // the larger value wins
    try std.testing.expect(better(2, 5, 1, 3));
    try std.testing.expect(!better(1, 3, 2, 5));
    // a tie goes to the lower index (either side's position)
    try std.testing.expect(better(1, 3, 1, 5));
    try std.testing.expect(!better(1, 5, 1, 3));
    // NaN above +inf and any value; NaN against NaN to the lower index
    const nan = std.math.nan(f32);
    try std.testing.expect(better(nan, 5, std.math.inf(f32), 3));
    try std.testing.expect(better(nan, 5, 1e30, 3));
    try std.testing.expect(!better(std.math.inf(f32), 3, nan, 5));
    try std.testing.expect(better(nan, 3, nan, 5));
    try std.testing.expect(!better(nan, 5, nan, 3));
    // -inf is a floor; equal -inf ties to the lower index
    const ninf = -std.math.inf(f32);
    try std.testing.expect(better(0, 1, ninf, 0));
    try std.testing.expect(better(ninf, 1, ninf, 2));
    // +inf ties to the lower index too
    try std.testing.expect(better(std.math.inf(f32), 1, std.math.inf(f32), 2));
}

test "biasElem rounds the rank-order fp32 dot to fp16 (even mantissa)" {
    // 1 * 0.5 + 1 * 0.5 = 1 exactly
    const head = [_]u16{ @as(u16, @bitCast(@as(f16, 1.0))), @as(u16, @bitCast(@as(f16, 1.0))) };
    const emb = [_]u16{ 0x3800, 0x3800 }; // bf16 0.5, 0.5
    try expectEqual(@as(u16, @bitCast(@as(f16, 1.0))), biasElem(&head, &emb));
    // 1 * 2^-12 + 1 * 2^-12 = 2^-11 exactly at fp16's smallest normal; 2^-13 + 2^-13 rounds to 2^-12 (even)
    const tiny = [_]u16{ @as(u16, @bitCast(@as(f16, 1.0))), @as(u16, @bitCast(@as(f16, 1.0))) };
    const e13 = [_]u16{ 0x3480, 0x3480 }; // bf16 2^-13 each: sum 2^-12 exactly
    try expectEqual(@as(u16, @bitCast(@as(f16, 0x1p-12))), biasElem(&tiny, &e13));
    // the even-mantissa rule: 2^-12 + 2^-13 = 3 * 2^-13 lands between 2^-12 and 1.5 * 2^-12 -> ties to 2^-12 (even)
    const e13b = [_]u16{ 0x3480, 0x3400 }; // bf16 2^-13, 2^-14
    try expectEqual(@as(u16, @bitCast(@as(f16, 0x1p-12))), biasElem(&tiny, &e13b));
}

test "step: a miss row's tiles, a hit row's cached bias and the tie rule to the lower id" {
    // cols 5 in tiles of 2 (3 tiles, the last one column); rank 2; seg0 1 -> ids 2..6
    const cols: usize = 5;
    const bc: usize = 2;
    const rank: usize = 2;
    const seg0: usize = 1;
    var head: [cols * rank]u16 = @splat(0);
    // miss row (token 7): make every column's bias 1.0 (head rows [1, 0] of a bf16 1.0 embedding)
    for (0..cols) |c| {
        head[c * rank + 0] = @bitCast(@as(f16, 1.0));
    }
    const emb_row = [_]u16{ 0x3F80, 0 }; // bf16 1.0, 0
    var emb: [10 * rank]u16 = @splat(0);
    @memcpy(emb[7 * rank ..][0..rank], &emb_row);
    const lg = [_]f32{
        0.0, 1.0, // tile 0: id 2 = 1.0 + 1.0 = 2.0, id 3 = 1.0 tie on 2.0 -> id 2 wins
        2.0, 2.0, // tile 1: ids 4 and 5 tie at 3.0 -> id 4 wins
        -4.0, // tile 2: id 6
    };
    const slot = [_]i32{ -1, -1 }; // token 7 misses (slot lookup other than its own entry is not needed here)
    const tok = [_]i64{7};
    var cache: [0]u16 = .{};
    var tiles: [3]f32 = undefined;
    var ids: [3]i32 = undefined;
    // the step's slot table covers tokens 0..1 above; token 7 reads slot[7] -> use a table that has it
    const slot7 = blk: {
        var s: [10]i32 = @splat(-1);
        break :blk s;
    };
    _ = slot;
    const out = step(1, cols, bc, rank, seg0, &lg, &slot7, &tok, &cache, &emb, &head, &tiles, &ids);
    try expectEqual(@as(f32, 2.0), tiles[0]);
    try expectEqual(@as(i32, 2), ids[0]);
    try expectEqual(@as(f32, 3.0), tiles[1]);
    try expectEqual(@as(i32, 4), ids[1]);
    try expectEqual(@as(f32, -3.0), tiles[2]);
    try expectEqual(@as(i32, 6), ids[2]);
    try expectEqual(@as(i64, 2), out); // the best of the tiles: id 2 at 2.0 (a tie to the lower id)
}

test "step: a hit row adds its cached bias and a NaN logit wins its tile" {
    const cols: usize = 4;
    const bc: usize = 2;
    const rank: usize = 1;
    const seg0: usize = 0;
    var head: [cols * rank]u16 = @splat(0);
    const lg = [_]f32{ 0.0, 1.0, std.math.nan(f32), -std.math.inf(f32) };
    var slot: [4]i32 = @splat(-1);
    slot[3] = 0; // token 3 has cached row 0
    const tok = [_]i64{3};
    // cached row 0: [0.5, 0.5, 0.5, 0.5] fp16
    const cache = [_]u16{ @as(u16, @bitCast(@as(f16, 0.5))), @bitCast(@as(f16, 0.5)), @bitCast(@as(f16, 0.5)), @bitCast(@as(f16, 0.5)) };
    var emb: [2 * rank]u16 = @splat(0);
    var tiles: [2]f32 = undefined;
    var ids: [2]i32 = undefined;
    const out = step(1, cols, bc, rank, seg0, &lg, &slot, &tok, &cache, &emb, &head, &tiles, &ids);
    try expectEqual(@as(f32, 1.5), tiles[0]); // 1.0 + 0.5 beats 0.0 + 0.5
    try expectEqual(@as(i32, 1), ids[0]);
    try std.testing.expect(tiles[1] != tiles[1]); // the NaN logit's tile
