//! TF_DS_MARKOV_FUSED (off by default): a greedy draft step's Markov bias miss rows and its tile scoring in one
//! launch (tf_ds_markov_fused_kernel, dsv41_ops.cu) instead of the kit's _bias then _score. Pure: no cuda import; the
//! launcher is Ops.markovFused and the call site is draft.zig's Markov loop (tri_markov.Markov.stepsFused). A malformed
//! switch refuses startup.
//!
//! On a cache miss _bias computes the step's bias row, rounds it to fp16 into the staging rows and _score rereads it:
//! 64,640 staged fp16 values per missed stream, step and rank (252.5 KiB of write and reread at the served 129,280
//! vocabulary on TP2). The fused kernel computes the miss rows' bias and adds the logits without staging: the round to
//! fp16 stays (the drafts are bit-identical), the staging rows are not written (greedy steps have no later reader of
//! them; a step that may be sampled keeps the old path and its staged bias for the sampled hook).
const std = @import("std");

pub const env_name: [:0]const u8 = "TF_DS_MARKOV_FUSED";

/// The switch's value: unset, "" or "0" off; "1" on; anything else is a refusal to start (the message is on stderr).
pub fn parse(text: ?[]const u8) ?bool {
    const t = text orelse return false;
    if (t.len == 0 or std.mem.eql(u8, t, "0")) return false;
    if (std.mem.eql(u8, t, "1")) return true;
    std.debug.print("{s}: expected 1 or 0\n", .{env_name});
    return null;
}

pub fn fromText(text: ?[]const u8) error{BadMarkovFused}!bool {
    return parse(text) orelse error.BadMarkovFused;
}

/// Whether the fused launch supports this step's shapes (the call sites fall back to _bias + _score when it does not):
/// rows at the kernel's 16 (markov.NP), and the global ids and partials below the kernel's masked-column sentinel
/// (1 << 30, _score's BIG) so its 32-bit index fields hold them.
pub fn fuseOk(fused: bool, rows: usize, cols: usize, segs: usize, seg0: usize, rank: usize, n_part: usize) bool {
    return fused and rows >= 1 and rows <= 16 and cols >= 1 and segs >= 1 and rank >= 1 and n_part >= 1 and
        cols <= std.math.maxInt(c_int) and n_part <= std.math.maxInt(c_int) and
        (seg0 + segs) * cols <= (1 << 30);
}

// -- host reference (the kit's markov.py semantics: _bias, _score, _finish) ------------------------------------------

/// markov.py's _better: (v1, i1) before (v2, i2) in torch.argmax's order: NaN above everything, then the larger
/// value, ties (and NaN against NaN) to the lower index.
pub fn better(v1: f32, i1: i32, v2: f32, i2: i32) bool {
    const n1 = v1 != v1;
    const n2 = v2 != v2;
    const gt = (v1 > v2) or ((v1 == v2) and (i1 < i2));
    return (n1 and (!n2 or i1 < i2)) or (!n1 and !n2 and gt);
}

/// bf16 bits widened to fp32 (`.float()`, exact).
pub fn widen(b: u16) f32 {
    return @bitCast(@as(u32, b) << 16);
}

/// fp32 rounded to fp16 bits (round to nearest even).
pub fn round16(x: f32) u16 {
    return @bitCast(@as(f16, x));
}

/// fp16 bits widened to fp32 (exact).
pub fn widen16(h: u16) f32 {
    return @as(f32, @as(f16, @bitCast(h)));
}

/// _bias's element: fp16(head[v] . fp16(emb[tok])) — the fp32 dot in rank order (fp16 x fp16 products are exact),
/// rounded to fp16. `head` is the column's row of the head (fp16 bits), `emb` the token's row of the embedding (bf16).
pub fn biasElem(head: []const u16, emb: []const u16) u16 {
    std.debug.assert(head.len == emb.len);
    var acc: f32 = 0;
    for (head, emb) |w, e| acc += widen16(w) * widen16(round16(widen(e)));
    return round16(acc);
}

/// One step's tile winners and draft ids for `n` rows (markov.py's _score then _finish): for each row the bias is its
/// cached row (`cache` rows of `cols` fp16 when `slot[row's token] >= 0`) or, on a miss, `biasElem` over the token's
/// embedding row (bf16 `rank`) and each column's head row (fp16 `rank`, column c at `head[c * rank ..]`); widened,
/// plus the logit (row r at `lg[r * cols ..]`). Each tile of `bc` columns emits its best (value, id = `seg0 * cols +
/// c`) under `better` into `tiles` / `ids` ([n, tiles]); `out[r]` is the best of row r's tiles (the _finish fold).
pub fn step(n: usize, cols: usize, bc: usize, rank: usize, seg0: usize, lg: []const f32, slot: []const i32, tok: []const i64, cache: []const u16, emb: []const u16, head: []const u16, tiles: []f32, ids: []i32, out: []i64) void {
    const s_tiles = (cols + bc - 1) / bc;
    std.debug.assert(lg.len >= n * cols and tok.len >= n and tiles.len >= n * s_tiles and ids.len >= n * s_tiles and out.len >= n);
    for (0..n) |r| {
        const t: usize = @intCast(tok[r]);
        std.debug.assert(t < slot.len and (slot[t] < 0 or cache.len >= (@as(usize, @intCast(slot[t])) + 1) * cols));
        std.debug.assert((slot[t] >= 0) or emb.len >= (t + 1) * rank);
        for (0..s_tiles) |s| {
            var bv: f32 = -std.math.inf(f32);
            var bi: i32 = 1 << 30;
            const c0 = s * bc;
            for (c0..@min(c0 + bc, cols)) |c| {
                std.debug.assert(slot[t] >= 0 or head.len >= (c + 1) * rank);
                const bias: u16 = if (slot[t] >= 0)
                    cache[@as(usize, @intCast(slot[t])) * cols + c]
                else
                    biasElem(head[c * rank ..][0..rank], emb[t * rank ..][0..rank]);
                const sc = lg[r * cols + c] + widen16(bias);
                const v: i32 = @intCast(seg0 * cols + c);
                if (better(sc, v, bv, bi)) {
                    bv = sc;
                    bi = v;
                }
            }
            tiles[r * s_tiles + s] = bv;
            ids[r * s_tiles + s] = bi;
        }
        var bv: f32 = -std.math.inf(f32);
        var bi: i32 = 1 << 30;
        for (0..s_tiles) |s| if (better(tiles[r * s_tiles + s], ids[r * s_tiles + s], bv, bi)) {
            bv = tiles[r * s_tiles + s];
            bi = ids[r * s_tiles + s];
        };
        out[r] = bi;
    }
}

