test "fuseOk takes the step's bounds" {
    try std.testing.expect(fuseOk(true, 1, 64640, 1, 1, 256, 64));
    try std.testing.expect(fuseOk(true, 16, 128, 2, 0, 1, 1));
    try std.testing.expect(!fuseOk(false, 1, 64640, 1, 1, 256, 64));
    try std.testing.expect(!fuseOk(true, 0, 64640, 1, 1, 256, 64));
    try std.testing.expect(!fuseOk(true, 17, 64640, 1, 1, 256, 64));
    try std.testing.expect(!fuseOk(true, 4, 0, 1, 1, 256, 64));
    try std.testing.expect(!fuseOk(true, 4, 64640, 1, 1, 0, 64));
    try std.testing.expect(!fuseOk(true, 4, 64640, 1, 1, 256, 0));
    // the global ids stay below the masked column's sentinel (1 << 30)
    try std.testing.expect(fuseOk(true, 4, 1 << 29, 1, 0, 256, 64));
    try std.testing.expect(!fuseOk(true, 4, 1 << 29, 1, 1, 256, 64));
}

test "better is torch.argmax's order: NaN above everything, ties to the lower index" {
    const nan = std.math.nan(f32);
    const ninf = -std.math.inf(f32);
    const pinf = std.math.inf(f32);
    // the larger value wins
    try std.testing.expect(better(2, 5, 1, 3));
    try std.testing.expect(!better(1, 3, 2, 5));
    // a tie goes to the lower index (either side's position)
    try std.testing.expect(better(1, 3, 1, 5));
    try std.testing.expect(!better(1, 5, 1, 3));
    // NaN above +inf and any value; NaN against NaN to the lower index
    try std.testing.expect(better(nan, 5, pinf, 3));
    try std.testing.expect(better(nan, 5, 1e30, 3));
    try std.testing.expect(!better(pinf, 3, nan, 5));
    try std.testing.expect(better(nan, 3, nan, 5));
    try std.testing.expect(!better(nan, 5, nan, 3));
    // -inf is a floor; equal values (including -inf and +inf) tie to the lower index
    try std.testing.expect(better(0, 1, ninf, 0));
    try std.testing.expect(better(ninf, 1, ninf, 2));
    try std.testing.expect(better(pinf, 1, pinf, 2));
}

test "biasElem: the rank-order fp32 dot rounds to fp16 (nearest, ties to even)" {
    const one = @as(u16, @bitCast(@as(f16, 1.0)));
    // 1 * 1 + 1 * 0.5 = 1.5 exactly
    try expectEqual(round16(1.5), biasElem(&.{ one, one }, &.{ b16(1.0), b16(0.5) }));
    // 1 + 2^-11 sits exactly between fp16's 1 and 1 + 2^-10: ties to even -> 1
    try expectEqual(one, biasElem(&.{ one, one }, &.{ b16(1.0), b16(0x1p-11) }));
    // 1 + 3 * 2^-11 sits exactly between 1 + 2^-10 and 1 + 2^-9: ties to even -> 1 + 2^-9
    try expectEqual(round16(1.0 + 0x1p-9), biasElem(&.{ one, one }, &.{ b16(1.0), b16(0x1.8p-10) }));
    // the embedding's bf16 rounds to fp16 first: bf16 1 + 2^-8 rounds to fp16 1 + 2^-8 (exact at this magnitude)
    try expectEqual(round16(1.0 + 0x1p-8), biasElem(&.{ one }, &.{ b16(1.0 + 0x1p-8) }));
}

test "step: a miss row's tiles, a hit row's cached bias, ties to the lower id" {
    // cols 5 in tiles of 2 (the last tile one column); rank 2; seg0 1 -> ids 2..6; two rows
    const cols: usize = 5;
    const bc: usize = 2;
    const rank: usize = 2;
    const seg0: usize = 1;
    var head: [cols * rank]u16 = @splat(0);
    for (0..cols) |c| head[c * rank] = @bitCast(@as(f16, 1.0)); // every column's bias = fp16(1 * 1 + 0)
    var emb: [8 * rank]u16 = @splat(0);
    emb[7 * rank] = b16(1.0); // token 7's row: bf16 [1, 0] -> the miss rows' bias 1 everywhere
    emb[3 * rank] = b16(1.0);
    // row 0 (token 7, miss): bias 1 everywhere; row 1 (token 3, hit) has cached row 0
    const lg = [_]f32{
        0.0, 1.0, // tile 0: id 2 = 2.0, id 3 = 2.0 tie -> id 2
        2.0, 2.0, // tile 1: id 4 = 3.0, id 5 = 3.0 tie -> id 4
        -4.0, // tile 2: id 6 = -3.0
        -std.math.inf(f32), 0.5, // row 1 tile 0: cached bias 0.5 -> ids 2, 3 at -inf + 0.5, 1.0 -> id 3
        1.0, 1.0, // row 1 tile 1: ids 4, 5 tie at 1.5 -> id 4
        2.0, // row 1 tile 2: id 6 at 2.5
    };
    var slot: [8]i32 = @splat(-1);
    slot[3] = 0;
    const tok = [_]i64{ 7, 3 };
    const cache = [_]u16{ @bitCast(@as(f16, 0.5)), @bitCast(@as(f16, 0.5)), @bitCast(@as(f16, 0.5)), @bitCast(@as(f16, 0.5)), @bitCast(@as(f16, 0.5)) };
    var tiles: [2 * 3]f32 = undefined;
    var ids: [2 * 3]i32 = undefined;
    var out: [2]i64 = undefined;
    step(2, cols, bc, rank, seg0, &lg, &slot, &tok, &cache, &emb, &head, &tiles, &ids, &out);
    // row 0: tile bests (2.0, 2), (3.0, 4), (-3.0, 6) -> id 4
    try expectEqual(@as(f32, 2.0), tiles[0]);
    try expectEqual(@as(i32, 2), ids[0]);
    try expectEqual(@as(f32, 3.0), tiles[1]);
    try expectEqual(@as(i32, 4), ids[1]);
    try expectEqual(@as(f32, -3.0), tiles[2]);
    try expectEqual(@as(i32, 6), ids[2]);
    try expectEqual(@as(i64, 4), out[0]);
    // row 1: the cached row biases every column 0.5; the -inf logit's id 2 loses to id 3
    try expectEqual(@as(f32, 1.0), tiles[3]);
    try expectEqual(@as(i32, 3), ids[3]);
    try expectEqual(@as(f32, 1.5), tiles[4]);
    try expectEqual(@as(i32, 4), ids[4]);
    try expectEqual(@as(f32, 2.5), tiles[5]);
    try expectEqual(@as(i32, 6), ids[5]);
    try expectEqual(@as(i64, 6), out[1]);
}

test "step: a NaN logit wins its tile and the row; a masked tail column never wins" {
    // cols 3 in tiles of 2: tile 1 has one masked column (ids 0..2, seg0 0)
    const cols: usize = 3;
    const bc: usize = 2;
    const rank: usize = 1;
    var head: [cols * rank]u16 = @splat(0);
    var emb: [4 * rank]u16 = @splat(0);
    const lg = [_]f32{ 0.0, 1.0, std.math.nan(f32) };
    var slot: [4]i32 = @splat(-1);
    const tok = [_]i64{3};
    var tiles: [2]f32 = undefined;
    var ids: [2]i32 = undefined;
    var out: [1]i64 = undefined;
    step(1, cols, bc, rank, 0, &lg, &slot, &tok, &.{}, &emb, &head, &tiles, &ids, &out);
    try expectEqual(@as(f32, 1.0), tiles[0]);
    try expectEqual(@as(i32, 1), ids[0]);
    try std.testing.expect(tiles[1] != tiles[1]); // the NaN column's tile
    try expectEqual(@as(i32, 2), ids[1]); // the one valid column of the short tile, not the masked sentinel
    try expectEqual(@as(i64, 2), out[0]); // NaN above everything
    // an all -inf row: the tiles tie at -inf and the fold takes the lower id; the masked column is not it
    const l2 = [_]f32{ -std.math.inf(f32), -std.math.inf(f32), -std.math.inf(f32) };
    step(1, cols, bc, rank, 0, &l2, &slot, &tok, &.{}, &emb, &head, &tiles, &ids, &out);
    try expectEqual(@as(i32, 0), ids[0]);
    try expectEqual(@as(i32, 2), ids[1]);
    try expectEqual(@as(i64, 0), out[0]);
}

