/// markov.py's _better: (va, ia) before (vb, ib) in torch.argmax's order: NaN above everything, then the larger
/// value, ties (and NaN against NaN) to the lower index.
pub fn better(va: f32, ia: i32, vb: f32, ib: i32) bool {
    const na = va != va;
    const nb = vb != vb;
    const gt = (va > vb) or ((va == vb) and (ia < ib));
    return (na and (!nb or ia < ib)) or (!na and !nb and gt);
}

