/// Whether the fused launch supports this step's shapes (the call sites fall back to _bias + _score when it does not):
/// rows at the kernel's 16 (markov.NP), the partials one per scoring tile of `bc` columns a segment, and the global ids
/// below the kernel's masked-column sentinel (1 << 30, _score's BIG) so its 32-bit index fields hold them.
pub const bc = 1024; // markov.BC: the kernel's scoring tile (markov_fused's grid.x is the segments' tiles)

pub fn fuseOk(fused: bool, rows: usize, cols: usize, segs: usize, seg0: usize, rank: usize, n_part: usize) bool {
    return fused and rows >= 1 and rows <= 16 and cols >= 1 and segs >= 1 and rank >= 1 and
        cols <= std.math.maxInt(c_int) and n_part <= std.math.maxInt(c_int) and
        n_part == ((cols + bc - 1) / bc) * segs and (seg0 + segs) * cols <= (1 << 30);
}

