/// TF_DS_MARKOV_FUSED: a greedy draft step's Markov bias miss rows and its tile scoring in one launch
/// (markov_fused's shapes as _bias and _score take them): PV / PI [rows, n_part] as _score writes them, the
/// staging rows untouched. The grid is _score's: the segment's tiles of `markov_fused.bc` columns.
pub fn markovFused(o: *const Ops, s: cuda.Stream, x: markov_fused.FusedArgs) !void {
    const f = o.markov_fused_fn orelse return error.MarkovFusedOff;
    if (!markov_fused.fuseOk(true, x.n_rows, x.cols, x.segs, x.seg0, x.rank, x.n_part)) return error.MarkovFusedShape;
