    a.add(@as(c_ulonglong, @intCast(x.t_stride)));
    a.add(x.slot);
    a.add(x.cache);
    a.add(@as(c_ulonglong, @intCast(x.c_row)));
    a.add(x.emb);
    a.add(x.head);
    a.add(@as(c_int, @intCast(x.rank)));
    a.add(x.pv);
    a.add(x.pi);
    a.add(@as(c_int, @intCast(x.n_rows)));
    a.add(@as(c_int, @intCast(x.cols)));
    a.add(@as(c_int, @intCast(x.seg0)));
