static RefPrune ref_prune(const int* pick, const float* wts, int topk, float topp, int min_k, int renorm, int apply) {
    int p[8]; float w[8], tot = 0.0f; int live = 0;
    for (int i = 0; i < topk; ++i) { p[i] = pick[i]; w[i] = wts[i]; if (p[i] >= 0) { ++live; tot += w[i]; } }
    RefPrune r; memcpy(r.pick, p, sizeof p); memcpy(r.wts, w, sizeof w); r.dropped = 0; r.mass = 0.0f;
    if (live == 0 || !(tot > 0) || isinf(tot)) return r;
    float f[8]; int rank[8];
    for (int i = 0; i < topk; ++i) f[i] = p[i] >= 0 ? w[i] / tot : 0.0f;
    for (int i = 0; i < topk; ++i) { rank[i] = 0; if (p[i] < 0) continue;
        for (int j = 0; j < topk; ++j) rank[i] += (p[j] >= 0 && (f[j] > f[i] || (f[j] == f[i] && j < i))) ? 1 : 0; }
    float run = 0.0f;
    float ex[8]; for (int k = 0; k < live; ++k) for (int i = 0; i < topk; ++i) if (p[i] >= 0 && rank[i] == k) { ex[i] = run; run += f[i]; }
    int floor_k = min_k > 1 ? min_k : 1;
    bool keep[8]; int kept = 0; float ks = 0.0f, mass = 0.0f;
    for (int i = 0; i < topk; ++i) {
        keep[i] = p[i] < 0 || rank[i] < floor_k || ex[i] < topp;
        if (p[i] < 0) continue;
        if (keep[i]) { ++kept; ks += w[i]; } else mass += f[i];
    }
    if (kept == live) return r;
    if (apply) {
        float g = tot / ks;
        for (int i = 0; i < topk; ++i) {
            if (p[i] < 0) continue;
            if (keep[i]) { if (renorm) w[i] *= g; }
            else { p[i] = -1; w[i] = 0.0f; }
        }
        memcpy(r.pick, p, sizeof p); memcpy(r.wts, w, sizeof w);
    }
    r.dropped = live - kept; r.mass = mass;
    return r;
}
