arguments.content:
// CPU harness for tf_ds_markov_fused_kernel (TF_DS_MARKOV_FUSED): the kernel's exact source (fused_kernel_current.inc,
// extracted from the worktree's dsv41_ops.cu by splice.py) under 256-thread block emulation, compared against an
// independent reference written from the brief and the kit's markov.py semantics: bias -> fp16 round -> add ->
// tile argmax with torch.argmax's tie rule (NaN above everything, ties to the lower index), then the row's best of
// the tiles (what _finish does on the fused path). NOT a model of Triton's or CUDA's codegen: it checks this C source
// bit for bit in fp32 IEEE (x86-64, SSE2, compiled -ffp-contract=off).
#include <cfloat>
#include <cmath>
#include <condition_variable>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fenv.h>
#include <mutex>
#include <thread>
#include <vector>

#define __global__
#define __device__
#define __shared__
#define __forceinline__ inline
#define __launch_bounds__(...)
#define __restrict__ __restrict__

struct dim3 {
    unsigned x, y, z;
};
thread_local dim3 threadIdx, blockIdx, gridDim, blockDim;

// -- block emulation: the kernel's __shared__ state and its barrier ----------------------------------------------
struct Barrier {
    std::mutex m;
    std::condition_variable cv;
    int count = 0, generation = 0;
    void arrive(int n) {
        asm volatile("" ::: "memory");
        std::unique_lock lk(m);
        int g = generation;
        if (++count == n) {
            count = 0;
            ++generation;
            lk.unlock();
            cv.notify_all();
            asm volatile("" ::: "memory");
            return;
        }
        cv.wait(lk, [&] { return generation != g; });
        asm volatile("" ::: "memory");
    }
};
struct SimBlock {
    float sv[256];
    int si[256];
    Barrier bar;
    void clear_shm() {
        std::memset(sv, 0, sizeof sv);
        std::memset(si, 0, sizeof si);
    }
};
thread_local SimBlock* blk = nullptr;
static inline void __syncthreads() { blk->bar.arrive(256); }

// -- fp16 / bf16 primitives (the device conversions; rounding to nearest even) ----------------------------------
struct __half {
    uint16_t __x;
};
struct __nv_bfloat16 {
    uint16_t __x;
};
static inline float __half2float(__half h) {
    unsigned s = (h.__x >> 15) & 1, e = (h.__x >> 10) & 0x1f, m = h.__x & 0x3ff;
    unsigned bits;
    if (e == 0) {
        if (m == 0) bits = s << 31;
        else { // a subnormal half is a normal float with a smaller exponent
            int shift = 0;
            unsigned mm = m;
            while ((mm & 0x400) == 0) {
                mm <<= 1;
                ++shift;
            }
            bits = (s << 31) | ((127 - 15 - shift) << 23) | ((mm & 0x3ff) << 13);
        }
    } else if (e == 0x1f) bits = (s << 31) | (0xffu << 23) | (m << 13); // inf / NaN
    else bits = (s << 31) | ((e + 112) << 23) | (m << 13);
    float r;
    memcpy(&r, &bits, 4);
    return r;
}
static inline __half __float2half_rn(float f) {
    unsigned u;
    memcpy(&u, &f, 4);
    unsigned s = (u >> 16) & 0x8000u;
    unsigned m = u & 0x7fffffu;
    int e = (int)((u >> 23) & 0xffu) - 127 + 15;
    __half h;
    if (((u >> 23) & 0xffu) == 0xffu) { // inf / NaN -> inf, quiet NaN
        h.__x = (uint16_t)(s | 0x7c00u | (m ? 0x200u : 0));
        return h;
    }
    if (e <= 0) {
        if (e < -10) {
            h.__x = (uint16_t)s;
            return h;
        }
        m |= 0x800000u;
        int shift = 1 - e + 13;
        unsigned rem = m & ((1u << shift) - 1);
        unsigned half = m >> shift;
        unsigned halfway = 1u << (shift - 1);
        if (rem > halfway || (rem == halfway && (half & 1))) ++half;
        h.__x = (uint16_t)(s | half);
        return h;
    }
    if (e >= 31) {
        h.__x = (uint16_t)(s | 0x7c00u);
        return h;
    }
    unsigned lsb = (m >> 13) & 1;
    m += 0xfffu + lsb;
    if (m & 0x800000u) {
        m = 0;
        ++e;
        if (e >= 31) {
            h.__x = (uint16_t)(s | 0x7c00u);
            return h;
        }
    }
    h.__x = (uint16_t)(s | ((unsigned)e << 10) | (m >> 13));
    return h;
}
static inline float __bfloat162float(__nv_bfloat16 v) {
    unsigned bits = (unsigned)v.__x << 16;
    float r;
    memcpy(&r, &bits, 4);
    return r;
}
static inline float __fadd_rn(float a, float b) { return a + b; }
static inline float __fmul_rn(float a, float b) { return a * b; }
static inline void pdl_enter(int) {}

// -- the kernel's exact source ---------------------------------------------------------------------------------
#ifdef MUTANT
#include "fused_kernel_mut.inc"
#else
#include "fused_kernel_current.inc"
#endif

// -- the independent reference ---------------------------------------------------------------------------------
// Written from the brief and the kit's markov.py spec, not from the kernel: for each row the bias is its cached row
// (slot[tok] >= 0) or fp16(head[v] . fp16(emb[tok])) with the dot accumulated in fp32 in rank order; widened, plus
// the logit; each tile's best (value, id) under torch.argmax's order; the row's best of the tiles is its draft id.

// fp16 rounding to nearest even, written from the IEEE-754 spec (normalize with frexp, round the significand to the
// kept bits with the FPU's round-to-nearest-even, rebuild; overflow carries to inf, subnormals lose bits below 2^-24).
static uint16_t ref_f16(float x) {
    if (std::isnan(x)) return 0x7e00u; // any NaN -> quiet canonical (the payload is not part of the rule)
    const uint16_t sgn = std::signbit(x) ? 0x8000u : 0u;
    const double a = std::fabs((double)x);
    if (a == 0.0) return sgn;
    int e;
    (void)std::frexp(a, &e); // a = m . 2^e, m in [1/2, 1): the value is 1.f . 2^(e-1)
    int exp = e - 1;
    int frac_bits = 10;
    if (exp < -14) frac_bits = 10 + (exp + 14); // a subnormal keeps fewer bits
    if (frac_bits < 0) return (a > 0x1p-25) ? (uint16_t)(sgn | 1u) : sgn; // half the smallest step: ties to even
    double scaled = std::ldexp(a, frac_bits + 1); // ... in half-step units
    long long v = (long long)std::nearbyint(scaled); // nearest, ties to even (FE_TONEAREST)
    if (v >= (1LL << (frac_bits + 1))) {
        v >>= 1;
        ++exp; // the rounding carried into the next exponent
    }
    if (exp > 15) return (uint16_t)(sgn | 0x7c00u); // overflow -> inf (65520 ties to even: inf)
    unsigned frac = (unsigned)v & ((1u << frac_bits) - 1);
    if (exp < -14) return (uint16_t)(sgn | frac); // subnormal (the exponent field stays 0)
    return (uint16_t)(sgn | ((unsigned)(exp + 15) << 10) | frac);
}

static float ref_widen16(uint16_t h) { return __half2float({h}); }
static float ref_widenbf16(uint16_t b) { return __bfloat162float({(uint16_t)b}); }

// torch.argmax's order from the spec: a NaN beats any non-NaN; two NaNs and any equal values take the lower index.
static bool ref_better(float a, int ia, float b, int ib) {
    bool na = a != a, nb = b != b;
    if (na != nb) return na;
    if (na) return ia < ib;
    if (a != b) return a > b;
    return ia < ib;
}

// one bias element: fp16(head[v] . fp16(emb[tok])), the fp32 dot in rank order
static uint16_t ref_bias_elem(const uint16_t* head, const uint16_t* efp, int rank) {
    float acc = 0.0f;
    for (int k = 0; k < rank; ++k) acc = acc + ref_widen16(head[k]) * efp[k];
    return ref_f16(acc);
}

// -- the case's buffers and both pipelines -----------------------------------------------------------------------
static uint64_t g_seed = 12345;
static uint64_t rnd() {
    g_seed = g_seed * 6364136223846793005ULL + 1442695040888963407ULL;
    return g_seed >> 17;
}

struct Case {
    int n_rows, cols, segs, seg0, rank, t_stride, l_row_extra, l_seg_extra;
    int n_part, c_row, l_row, l_seg, slot_rows, lg_len;
    std::vector<float> lg;
    std::vector<int64_t> tok;
    std::vector<int32_t> slot;
    std::vector<uint16_t> cache, emb, head;
    std::vector<int> hit; // per row: its cache slot, or -1

    void build(int n_rows_, int cols_, int segs_, int seg0_, int rank_, bool pad) {
        n_rows = n_rows_;
        cols = cols_;
        segs = segs_;
        seg0 = seg0_;
        rank = rank_;
        t_stride = pad ? 3 : 1;
        l_row_extra = pad ? 5 : 0;
        l_seg_extra = pad ? 7 : 0;
        n_part = ((cols + 1023) / 1024) * segs;
        c_row = segs * cols;
        l_row = cols + l_row_extra;
        l_seg = n_rows * l_row + l_seg_extra;
        slot_rows = 0;
        lg_len = segs * l_seg + n_rows * l_row + cols;
        lg.assign(lg_len, 0.0f);
        tok.assign((size_t)t_stride * n_rows, 0);
        slot.assign(1, -1);
        cache.clear();
        emb.clear();
        head.assign((size_t)(seg0 + segs) * cols * rank, 0);
        hit.assign(n_rows, -1);
    }

    // tokens 0..n-1 per row, `slots` of them cached (row r hits at slot r when r < hits, slot 0 pinned first)
    void tokens(int hits, bool pin0) {
        for (int r = 0; r < n_rows; ++r) tok[(size_t)r * t_stride] = r;
        slot.assign(n_rows + 1, -1);
        slot_rows = hits > 0 ? hits : 0;
        if (pin0 && hits > 0) {
            hit.assign(n_rows, -1);
            hit[0] = 0;
            slot[0] = 0;
            for (int r = 1; r < hits && r < n_rows; ++r) {
                hit[r] = r;
                slot[r] = r;
            }
        } else {
            for (int r = 0; r < hits && r < n_rows; ++r) {
                hit[r] = r;
                slot[r] = r;
            }
        }
        if (slot_rows > 0) cache.assign((size_t)slot_rows * c_row, 0);
    }
};

// fill helpers: logits / bias values from small pools (ties and specials by construction) or random bits
static void fill_pool(Case& c, bool specials) {
    static const float pool[] = { 0.0f, 1.0f, -1.0f, 2.0f, 0.5f, -0.0f };
    static const float spool[] = { 0.0f, 1.0f, INFINITY, -INFINITY, 1e30f, -3.0f };
    for (int r = 0; r < c.n_rows; ++r)
        for (int j = 0; j < c.cols; ++j) {
            float v = specials ? spool[(r * 7 + j * 13) % 6] : pool[(r * 5 + j * 11) % 6];
            if (specials && (r * 17 + j) % 23 == 0) {
                unsigned nanb = 0x7fc00000u + (unsigned)(j & 7);
                memcpy(&v, &nanb, 4);
            }
            for (int s = 0; s < c.segs; ++s) c.lg[(size_t)s * c.l_seg + (size_t)r * c.l_row + j] = v;
        }
    // bias rows: cached rows and head/emb entries of halves and small integers (their sums land on fp16 midpoints)
    static const uint16_t hp[] = { 0x3C00, 0x3800, 0x4000, 0x3400, 0x0000, 0xBC00 };
    for (size_t i = 0; i < c.cache.size(); ++i) c.cache[i] = hp[(i * 3) % 6];
    const size_t emb_rows = (size_t)c.n_rows + 1;
    c.emb.assign(emb_rows * c.rank, 0);
    for (size_t i = 0; i < c.emb.size(); ++i) c.emb[i] = hp[(i * 7) % 6] == 0xBC00 ? 0xBF00 : (hp[(i * 7) % 6] == 0x3400 ? 0x3500 : hp[(i * 7) % 6]);
    for (size_t i = 0; i < c.head.size(); ++i) c.head[i] = hp[(i * 5) % 6];
}

static void fill_random(Case& c) {
    for (size_t i = 0; i < c.lg.size(); ++i) {
        unsigned b = (unsigned)rnd() | (((unsigned)rnd() & 0xff) << 16);
        memcpy(&c.lg[i], &b, 4);
    }
    for (size_t i = 0; i < c.cache.size(); ++i) c.cache[i] = (uint16_t)rnd();
    for (size_t i = 0; i < c.emb.size(); ++i) c.emb[i] = (uint16_t)rnd();
    for (size_t i = 0; i < c.head.size(); ++i) c.head[i] = (uint16_t)rnd();
}

// the reference pipeline: bias -> fp16 round -> add -> tile argmax (ref_better) -> the row's best of the tiles
static void ref_step(const Case& c, std::vector<float>& pv, std::vector<int32_t>& pi, std::vector<int64_t>& ids) {
    const int s_tiles = (c.cols + 1023) / 1024;
    pv.assign((size_t)c.n_rows * c.n_part, 0.0f);
    pi.assign((size_t)c.n_rows * c.n_part, 0);
    ids.assign(c.n_rows, -1);
    std::vector<float> efp(c.rank);
    for (int r = 0; r < c.n_rows; ++r) {
        const int64_t t = c.tok[(size_t)r * c.t_stride];
        const int at = c.slot[(size_t)t];
        for (int k = 0; k < c.rank; ++k) efp[k] = ref_widen16(ref_f16(ref_widenbf16(c.emb[(size_t)t * c.rank + k])));
        for (int s = 0; s < c.segs; ++s) {
            for (int ti = 0; ti < s_tiles; ++ti) {
                float bv = -INFINITY;
                int bi = 1 << 30;
                for (int j = ti * 1024; j < (ti + 1) * 1024 && j < c.cols; ++j) {
                    float b = at >= 0 ? ref_widen16(c.cache[(size_t)at * c.c_row + (size_t)s * c.cols + j])
                        : ref_widen16(ref_bias_elem(&c.head[((size_t)(c.seg0 + s) * c.cols + j) * c.rank], efp.data(), c.rank));
                    float sc = c.lg[(size_t)s * c.l_seg + (size_t)r * c.l_row + j] + b;
                    int v = (c.seg0 + s) * c.cols + j;
                    if (ref_better(sc, v, bv, bi)) {
                        bv = sc;
                        bi = v;
                    }
                }
                int p = s * s_tiles + ti;
                pv[(size_t)r * c.n_part + p] = bv;
                pi[(size_t)r * c.n_part + p] = bi;
            }
        }
        // the _finish fold: the row's best of its tile winners, in the reverse order (the total order must agree)
        float bv = -INFINITY;
        int bi = 1 << 30;
        for (int p = c.n_part - 1; p >= 0; --p)
            if (ref_better(pv[(size_t)r * c.n_part + p], pi[(size_t)r * c.n_part + p], bv, bi)) {
                bv = pv[(size_t)r * c.n_part + p];
                bi = pi[(size_t)r * c.n_part + p];
            }
        ids[r] = bi;
    }
}

// the kernel's launches: grid (s_tiles, segs), 256 threads a block, one block at a time (blocks are independent)
static void run_kernel(Case& c, std::vector<float>& pv, std::vector<int32_t>& pi, std::vector<int64_t>& ids) {
    const int s_tiles = (c.cols + 1023) / 1024;
    pv.assign((size_t)c.n_rows * c.n_part, 0.0f);
    pi.assign((size_t)c.n_rows * c.n_part, 0);
    for (int by = 0; by < c.segs; ++by) for (int bx = 0; bx < s_tiles; ++bx) {
        SimBlock b;
        b.clear_shm();
        std::vector<std::thread> ts;
        for (int t = 0; t < 256; ++t) ts.emplace_back([&, t, bx, by]() {
            blk = &b;
            threadIdx = { (unsigned)t, 0, 0 };
            blockIdx = { (unsigned)bx, (unsigned)by, 0 };
            gridDim = { (unsigned)s_tiles, (unsigned)c.segs, 0 };
            blockDim = { 256, 0, 0 };
            tf_ds_markov_fused_kernel(
                c.lg.data(), (uint64_t)c.l_seg, (uint64_t)c.l_row, c.tok.data(), (uint64_t)c.t_stride, c.slot.data(),
                (const __half*)c.cache.data(), (uint64_t)c.c_row, (const __nv_bfloat16*)c.emb.data(),
                (const __half*)c.head.data(), c.rank, pv.data(), pi.data(), c.n_rows, c.cols, c.seg0, c.n_part, 0);
        });
        for (auto& th : ts) th.join();
    }
    // the fused path's unchanged _finish fold (the kernel's own _better), in the forward order
    ids.assign(c.n_rows, -1);
    for (int r = 0; r < c.n_rows; ++r) {
        float bv = -INFINITY;
        int bi = 1 << 30;
        for (int p = 0; p < c.n_part; ++p)
            if (tf_ds_markov_better(pv[(size_t)r * c.n_part + p], pi[(size_t)r * c.n_part + p], bv, bi)) {
                bv = pv[(size_t)r * c.n_part + p];
                bi = pi[(size_t)r * c.n_part + p];
            }
        ids[r] = bi;
    }
}

// -- the matrix -------------------------------------------------------------------------------------------------
static int g_cases = 0, g_fail = 0;

static bool same_bits(float a, float b) {
    uint32_t x, y;
    memcpy(&x, &a, 4);
    memcpy(&y, &b, 4);
    return x == y;
}

static void check(const char* name, Case& c) {
    std::vector<float> kpv, rpv;
    std::vector<int32_t> kpi, rpi;
    std::vector<int64_t> kids, rids;
    run_kernel(c, kpv, kpi, kids);
    ref_step(c, rpv, rpi, rids);
    ++g_cases;
    bool ok = true;
    for (size_t i = 0; i < kpv.size(); ++i)
        if (!same_bits(kpv[i], rpv[i]) || kpi[i] != rpi[i]) ok = false;
    for (int r = 0; r < c.n_rows; ++r)
        if (kids[r] != rids[r]) ok = false;
    if (!ok) {
        ++g_fail;
        printf("FAIL %s: rows=%d cols=%d segs=%d seg0=%d rank=%d hits=%d\n", name, c.n_rows, c.cols, c.segs, c.seg0, c.rank,
            (int)std::count_if(c.hit.begin(), c.hit.end(), [](int h) { return h >= 0; }));
        for (int r = 0; r < c.n_rows && r < 4; ++r) {
            for (int p = 0; p < c.n_part && p < 6; ++p) {
                size_t i = (size_t)r * c.n_part + p;
                printf("  row %d tile %d: kernel (%g,%d) ref (%g,%d)%s\n", r, p, kpv[i], kpi[i], rpv[i], rpi[i],
                    (!same_bits(kpv[i], rpv[i]) || kpi[i] != rpi[i]) ? "  <-- differs" : "");
            }
            if (kids[r] != rids[r]) printf("  row %d id: kernel %lld ref %lld  <-- differs\n", r, (long long)kids[r], (long long)rids[r]);
        }
    }
}

static void case_ties() {
    // one tile, one row: hand-checked winners under the tie rule
    {
        Case c;
        c.build(1, 1024, 1, 0, 1, false);
        c.tokens(0, false);
        fill_pool(c, false);
        // plant exact ties: equal logits and equal bias at columns 0, 7, 1023 -> the lowest id wins
        for (int j : { 0, 7, 1023 }) {
            c.lg[j] = 3.0f;
            c.head[(size_t)j * c.rank] = 0; // bias 0 everywhere
        }
        for (int j = 0; j < 1024; ++j) if (j != 0 && j != 7 && j != 1023) c.lg[j] = -9.0f;
        check("ties-lowest", c);
    }
    // two tiles: a tie across the tile boundary (the tile winners tie again at the fold)
    {
        Case c;
        c.build(1, 2048 + 128, 1, 3, 2, false);
        c.tokens(0, false);
        fill_pool(c, false);
        for (int s = 0; s < c.segs; ++s) for (int j = 0; j < c.cols; ++j) {
            c.lg[(size_t)s * c.l_seg + j] = 5.0f - 2.0f * (float)((j / 1024) % 2); // tiles tie at the fold
            c.head[((size_t)(c.seg0 + s) * c.cols + j) * c.rank] = 0x3C00; // bias 1
        }
        check("ties-across-tiles", c);
    }
    // tied NaNs at two columns of one tile -> the lower id; a NaN against +inf -> the NaN
    {
        Case c;
        c.build(2, 1500, 1, 0, 1, true);
        c.tokens(1, true); // row 0 hits at slot 0, row 1 misses
        fill_pool(c, true);
        unsigned nan = 0x7fc01234u;
        for (int s = 0; s < c.segs; ++s) {
            memcpy(&c.lg[(size_t)s * c.l_seg + 0 * c.l_row + 11], &nan, 4);
            memcpy(&c.lg[(size_t)s * c.l_seg + 0 * c.l_row + 44], &nan, 4);
            c.lg[(size_t)s * c.l_seg + 1 * c.l_row + 12] = INFINITY;
        }
        check("ties-nan", c);
    }
    // an all -inf row with a partial tile: the masked columns' sentinel never wins (the lowest valid id does)
    {
        Case c;
        c.build(1, 1025, 1, 0, 1, false); // one full tile and one of a single column
        c.tokens(0, false);
        fill_pool(c, false);
        for (int j = 0; j < c.cols; ++j) c.lg[j] = -INFINITY;
        check("ties-ninf-masked", c);
    }
}

static void case_specials() {
    for (int rows = 1; rows <= 4; ++rows) for (int mode = 0; mode < 3; ++mode) {
        Case c;
        c.build(rows, 2048 + 64, 1, 1, 3, mode == 2);
        c.tokens(rows > 1 ? rows - mode : 0, mode == 1); // all-miss, mixed (slot 0), all-hit
        fill_pool(c, true);
        check("specials", c);
    }
}

static void case_misses() {
    // misses for 1-4 streams (rows), each stream's row its own token
    for (int rows = 1; rows <= 4; ++rows) for (int hits = 0; hits <= rows; ++hits) {
        Case c;
        c.build(rows, 2500, 1, 2, 4, false);
        c.tokens(hits, hits > 0);
        fill_pool(c, false);
        check("misses", c);
    }
    // the same with two segments (a lone rank scores every column)
    for (int rows = 1; rows <= 4; ++rows) {
        Case c;
        c.build(rows, 1200, 2, 0, 2, true);
        c.tokens((rows + 1) / 2, true);
        fill_pool(c, true);
        check("misses-segs2", c);
    }
}

static void case_tiles() {
    for (int cols : { 1, 2, 127, 1023, 1024, 1025, 2048, 2049, 3000 }) for (int rows = 1; rows <= 3; rows += 2) {
        Case c;
        c.build(rows, cols, 1, 4, 1, rows > 1);
        c.tokens(rows > 1 ? 1 : 0, true);
        fill_pool(c, rows % 2 == 0);
        check("tiles", c);
    }
}

static void case_fuzz() {
    for (int n = 0; n < 120; ++n) {
        Case c;
        int rows = 1 + (int)(rnd() % 4);
        int cols = 1 + (int)(rnd() % 3000);
        int segs = 1 + (int)(rnd() % 2);
        c.build(rows, cols, segs, (int)(rnd() % 4), 1 + (int)(rnd() % 24), (rnd() & 1) != 0);
        int hits = (int)(rnd() % (unsigned)(rows + 1));
        c.tokens(hits, (rnd() & 1) != 0);
        fill_random(c);
        check("fuzz", c);
    }
}

static void case_served() {
    // the served shape: 64,640 columns a rank at TP2, rank 256, four streams, rank 1's half
    for (int rows = 1; rows <= 4; ++rows) {
        Case c;
        c.build(rows, 64640, 1, 1, 256, false);
        c.tokens(rows > 2 ? 1 : 0, true); // a mix of hits and misses
        fill_pool(c, false);
        // plant the tie and NaN cases at full width: the tile winners and the fold's winner
        for (int j : { 0, 1024, 64639 }) c.lg[j] = 2.0f;
        unsigned nan = 0x7fc00000u;
        memcpy(&c.lg[1025], &nan, 4);
        check("served", c);
    }
}

// the two rounding implementations (the kernel's __float2half_rn and the reference's ref_f16) must agree
static int check_rounding() {
    int bad = 0;
    auto sweep = [&](float f) {
        uint16_t a = __float2half_rn(f).__x, b = ref_f16(f);
        if (a != b) {
            if (bad < 5) printf("FAIL rounding: %.9g -> stub %04x ref %04x\n", (double)f, a, b);
            ++bad;
        }
    };
    for (float f : { 0.0f, -0.0f, 1.0f, -1.0f, 0.5f, 2.0f, 65504.0f, 65520.0f, 65536.0f, 1e30f, -1e30f, 0x1p-14f, 0x1p-15f, 0x1p-24f, 0x1p-25f, 3.0f * 0x1p-25f, 0x1p-26f }) sweep(f);
    for (int i = 0; i < 20000; ++i) {
        unsigned b = (unsigned)rnd();
        float f;
        memcpy(&f, &b, 4);
        sweep(f);
    }
    printf("rounding cross-check: %s (%d values)\n", bad ? "FAIL" : "ok", 20017);
    return bad;
}

int main() {
    fesetround(FE_TONEAREST); // ref_f16 rounds with nearbyint: nearest, ties to even
    int bad = check_rounding();
    case_ties();
    case_specials();
    case_misses();
    case_tiles();
    case_fuzz();
    case_served();
    printf("%d cases, %d failures%s\n", g_cases, g_fail + bad, g_fail + bad ? "" : ": ALL MATCH");
    return (g_fail + bad) ? 1 : 0;
}

// CPU harness for TF_DS_MARKOV_FUSED's tf_ds_markov_fused_kernel (h0267). It executes the kernel's exact source
// (fused_kernel_current.inc, extracted by splice.py from zig/kernels/cuda/dsv41_ops.cu) with emulated blocks/warps
// (256 OS threads a block, __syncthreads a barrier), against an INDEPENDENT reference written from BRIEF-0267 and the
// kit's markov.py spec: bias -> fp16 round -> + logit -> tile argmax with torch.argmax's tie rule (NaN above
// everything, ties -- and NaN against NaN -- to the lower index), then _finish's fold for the draft id.
//
// NOT a model of CUDA codegen: it checks this C source's logic and fp32 IEEE arithmetic (x86-64, SSE, compiled with
// -ffp-contract=off so `acc += w * e` is the kernel's --fmad=false MUL then ADD). The fp16 round is cross-checked
// between the stub's bit routine (the kernel's __float2half_rn) and the reference's _Float16 conversion (libgcc).
// GPU-only rounding points are listed in report-0267.md.
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <cstdlib>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <vector>
#include <random>

// ---- CUDA stubs (p0194/fused_run.cpp's pattern) -------------------------------------------------------------------
#define __global__
#define __device__
#define __shared__
#define __forceinline__ inline
#define __launch_bounds__(...)
struct dim3 { unsigned x, y, z; };
thread_local dim3 threadIdx, blockIdx, gridDim, blockDim;

struct Barrier {
    std::mutex m;
    std::condition_variable cv;
    int count = 0, generation = 0;
    void arrive(int n) {
        asm volatile("" ::: "memory");
        std::unique_lock lk(m);
        int g = generation;
        if (++count == n) { count = 0; ++generation; lk.unlock(); cv.notify_all(); asm volatile("" ::: "memory"); return; }
        cv.wait(lk, [&] { return generation != g; });
        asm volatile("" ::: "memory");
    }
};

struct SimBlock {
    float sv[256]; // the kernel's shared reduce partials (its __shared__ arrays, moved here by splice.py)
    int si[256];
    Barrier bar;
    void clear_shm() {
        std::memset(sv, 0, sizeof sv);
        std::memset(si, 0, sizeof si);
    }
};
thread_local SimBlock* blk = nullptr;
static SimBlock g_block;
static inline void __syncthreads() { blk->bar.arrive(256); }
static inline void pdl_enter(int) {}

struct __half { uint16_t __x; };
struct __nv_bfloat16 { uint16_t __x; };

// __half2float / __bfloat162float: the widenings, bit for bit (exact).
static inline float __half2float(__half h) {
    unsigned u = (unsigned)h.__x << 16;
    float f;
    memcpy(&f, &u, 4);
    return f;
}
static inline float __bfloat162float(__nv_bfloat16 b) {
    unsigned u = (unsigned)b.__x << 16;
    float f;
    memcpy(&f, &u, 4);
    return f;
}
// __float2half_rn: fp32 -> fp16, round to nearest even (IEEE-754), a NaN to the canonical quiet 0x7e00 (cvt.rn.f16.f32
// canonicalises). Bit manipulation, kept apart from the reference's _Float16 conversion; build.sh cross-checks them.
static inline __half __float2half_rn(float f) {
    unsigned u;
    memcpy(&u, &f, 4);
    unsigned s = (u >> 16) & 0x8000u;
    int e = (int)((u >> 23) & 0xffu) - 127 + 15;
    unsigned m = u & 0x7fffffu;
    __half h;
    if (((u >> 23) & 0xffu) == 0xffu && m != 0) { h.__x = (uint16_t)(s | 0x7e00u); return h; } // NaN -> canonical
    if (e <= 0) {
        if (e < -10) { h.__x = (uint16_t)s; return h; }
        m |= 0x800000u;
        int shift = 1 - e + 13;
        unsigned rem = m & ((1u << shift) - 1);
        unsigned half = m >> shift;
        unsigned halfway = 1u << (shift - 1);
        if (rem > halfway || (rem == halfway && (half & 1))) ++half;
        h.__x = (uint16_t)(s | half);
        return h;
    }
    if (e >= 31) { h.__x = (uint16_t)(s | 0x7c00u); return h; }
    unsigned lsb = (m >> 13) & 1;
    m += 0xfffu + lsb;
    if (m & 0x800000u) { m = 0; ++e; if (e >= 31) { h.__x = (uint16_t)(s | 0x7c00u); return h; } }
    h.__x = (uint16_t)(s | ((unsigned)e << 10) | (m >> 13));
    return h;
}

// ---- the kernel's exact source -------------------------------------------------------------------------------------
#include "fused_kernel_current.inc"

// ---- the independent reference (from BRIEF-0267 and markov.py's spec, not from the kernel) --------------------------
// The tie rule, as the spec words it: NaN above everything, then the larger value, ties (and NaN against NaN) to the
// lower index. Written as a predicate over "a beats b", in the opposite direction from the kernel's fold.
static bool ref_beats(float va, int ia, float vb, int ib) {
    const bool na = std::isnan(va), nb = std::isnan(vb);
    if (na != nb) return na; // NaN above everything
    if (na) return ia < ib; // NaN against NaN: the lower index
    if (va != vb) return va > vb; // the larger value
    return ia < ib; // a tie: the lower index
}

// fp32 -> fp16 bits, round to nearest even: the reference asks _Float16 (libgcc's conversion), a NaN pinned to the
// canonical quiet 0x7e00 the kernel's rounding takes.
static uint16_t ref_round16(float x) {
    if (std::isnan(x)) return 0x7e00u;
    _Float16 h = (_Float16)x;
    uint16_t bits;
    memcpy(&bits, &h, 2);
    return bits;
}
static float ref_widen16(uint16_t bits) {
    _Float16 h;
    memcpy(&h, &bits, 2);
    return (float)h;
}

// The step pipeline per row: bias = the token's cached row (slot >= 0) or fp16(head[v] . fp16(emb[tok])) per column
// (the fp32 dot in rank order), widened, plus the logit; each tile of `bc` columns emits its best (value, id) under
// ref_beats into out_tiles / out_ids ([rows, n_part], p = seg * s_tiles + tile); out_wins[r] folds row r's tiles.
struct RefOut {
    std::vector<float> tiles; // [rows, n_part] the winners' scores
    std::vector<int> ids; // [rows, n_part] the winners' global ids
    std::vector<long long> wins; // [rows] _finish's fold
};

static RefOut ref_step(int rows, int n_cols, int segs, int seg0, int rank, long long l_seg, long long l_row,
                       const float* LG, const long long* TOK, long long t_stride, const int* SLOT,
                       const uint16_t* CACHE, long long c_row, const uint16_t* EMB, const uint16_t* HEAD) {
    const int s_tiles = (n_cols + 1023) / 1024;
    const int n_part = s_tiles * segs;
    RefOut o;
    o.tiles.assign((size_t)rows * n_part, 0.0f);
    o.ids.assign((size_t)rows * n_part, 0);
    o.wins.assign(rows, -1);
    for (int r = 0; r < rows; ++r) {
        long long tok = TOK[(long long)r * t_stride];
        int slot = SLOT[tok];
        for (int s = 0; s < segs; ++s) {
            for (int t = 0; t < s_tiles; ++t) {
                float bv = -INFINITY;
                int bi = 1 << 30; // _score's masked columns fold (-inf, 1 << 30)
                int c0 = t * 1024;
                for (int c = c0; c < c0 + 1024 && c < n_cols; ++c) {
                    float b;
                    if (slot >= 0) {
                        b = ref_widen16(CACHE[(long long)slot * c_row + (long long)s * n_cols + c]);
                    } else {
                        // fp16(head[v] . fp16(emb[tok])): the fp32 dot in rank order, rounded to fp16, widened back
                        float acc = 0.0f;
                        for (int k = 0; k < rank; ++k) {
                            float wk = ref_widen16(HEAD[(size_t)((long long)(seg0 + s) * n_cols + c) * (unsigned)rank + k]);
                            float ek = ref_widen16(ref_round16(__bfloat162float(EMB[(size_t)tok * (unsigned)rank + k])));
                            acc += wk * ek;
                        }
                        b = ref_widen16(ref_round16(acc));
                    }
                    float sc = LG[(long long)s * l_seg + (long long)r * l_row + c] + b;
                    int v = (seg0 + s) * n_cols + c;
                    if (ref_beats(sc, v, bv, bi)) { bv = sc; bi = v; }
                }
                int p = s * s_tiles + t;
                o.tiles[(size_t)r * n_part + p] = bv;
                o.ids[(size_t)r * n_part + p] = bi;
            }
        }
        // _finish: the best of the row's tile winners
        float bv = -INFINITY;
        int bi = 1 << 30;
        for (int p = 0; p < n_part; ++p)
            if (ref_beats(o.tiles[(size_t)r * n_part + p], o.ids[(size_t)r * n_part + p], bv, bi)) {
                bv = o.tiles[(size_t)r * n_part + p];
                bi = o.ids[(size_t)r * n_part + p];
            }
        o.wins[r] = bi;
    }
    return o;
}

// ---- the emulated launch -------------------------------------------------------------------------------------------
// Blocks are independent (no grid-wide synchronisation), so they run one after another, each with 256 OS threads.
static void launch(int s_tiles, int segs, int rows, int n_cols, int seg0, int rank, long long l_seg, long long l_row,
                   float* LG, long long* TOK, long long t_stride, int* SLOT, uint16_t* CACHE, long long c_row,
                   uint16_t* EMB, uint16_t* HEAD, float* PV, int* PI, int n_part) {
    for (int s = 0; s < segs; ++s) {
        for (int t = 0; t < s_tiles; ++t) {
            g_block.clear_shm();
            std::vector<std::thread> ts;
            for (int i = 0; i < 256; ++i) {
                ts.emplace_back([=, &ts]() {
                    (void)&ts;
                    blk = &g_block;
                    threadIdx = { (unsigned)i, 0, 0 };
                    blockIdx = { (unsigned)t, (unsigned)s, 0 };
                    gridDim = { (unsigned)s_tiles, (unsigned)segs, 1 };
                    blockDim = { 256, 0, 0 };
                    tf_ds_markov_fused_kernel(LG, (uint64_t)l_seg, (uint64_t)l_row, TOK, (uint64_t)t_stride, SLOT,
                                              (const __half*)CACHE, (uint64_t)c_row, (const __nv_bfloat16*)EMB,
                                              (const __half*)HEAD, rank, PV, PI, rows, n_cols, seg0, n_part, 0);
                });
            }
            for (auto& th : ts) th.join();
        }
    }
}

// ---- checking ------------------------------------------------------------------------------------------------------
static int g_fail = 0;
static long long g_cases = 0, g_rows = 0;
#define CHECK(cond, ...) do { if (!(cond)) { ++g_fail; printf("FAIL: "); printf(__VA_ARGS__); printf("\n"); } } while (0)

struct Case {
    int rows, n_cols, segs, seg0, rank;
    long long l_seg, l_row, t_stride, c_row;
    std::vector<float> lg;
    std::vector<long long> tok;
    std::vector<int> slot;
    std::vector<uint16_t> cache, emb, head;
    std::vector<long long> tok_space; // the slot table's length (tokens drawn from [0, tok_space))
};

// Run one case through the emulated kernel and the reference; compare every tile winner's bits and id, and the drafts.
static void run_case(const char* name, Case& c) {
    ++g_cases;
    g_rows += c.rows;
    const int s_tiles = (c.n_cols + 1023) / 1024;
    const int n_part = s_tiles * c.segs;
    std::vector<float> pv((size_t)c.rows * n_part, 12345.0f);
    std::vector<int> pi((size_t)c.rows * n_part, -999);
    launch(s_tiles, c.segs, c.rows, c.n_cols, c.seg0, c.rank, c.l_seg, c.l_row, c.lg.data(), const_cast<long long*>(c.tok.data()),
           c.t_stride, const_cast<int*>(c.slot.data()), c.cache.data(), c.c_row, c.emb.data(), c.head.data(), pv.data(), pi.data(), n_part);
    RefOut ref = ref_step(c.rows, c.n_cols, c.segs, c.seg0, c.rank, c.l_seg, c.l_row, c.lg.data(), c.tok.data(), c.t_stride,
                          c.slot.data(), c.cache.data(), c.c_row, c.emb.data(), c.head.data());
    for (int r = 0; r < c.rows; ++r) {
        for (int p = 0; p < n_part; ++p) {
            float kv = pv[(size_t)r * n_part + p], rv = ref.tiles[(size_t)r * n_part + p];
            uint32_t kb, rb;
            memcpy(&kb, &kv, 4);
            memcpy(&rb, &rv, 4);
            CHECK(kb == rb, "%s row %d p %d: value bits %08x vs %08x", name, r, p, kb, rb);
            CHECK(pi[(size_t)r * n_part + p] == ref.ids[(size_t)r * n_part + p], "%s row %d p %d: id %d vs %d", name, r, p,
                  pi[(size_t)r * n_part + p], ref.ids[(size_t)r * n_part + p]);
        }
        // the greedy draft id (_finish's fold over the kernel's own partials)
        float bv = -INFINITY;
        int bi = 1 << 30;
        for (int p = 0; p < n_part; ++p)
            if (ref_beats(pv[(size_t)r * n_part + p], pi[(size_t)r * n_part + p], bv, bi)) {
                bv = pv[(size_t)r * n_part + p];
                bi = pi[(size_t)r * n_part + p];
            }
        CHECK(bi == ref.wins[r], "%s row %d: draft id %lld vs %lld", name, r, (long long)bi, ref.wins[r]);
    }
}

// ---- case construction ---------------------------------------------------------------------------------------------
static uint16_t f16_bits(float f) { return __float2half_rn(f).__x; }
static uint16_t b16_bits(float f) {
    unsigned u;
    memcpy(&u, &f, 4);
    return (uint16_t)(u >> 16);
}

static Case make_case(int rows, int n_cols, int segs, int seg0, int rank, long long t_stride, long long block) {
    Case c;
    c.rows = rows;
    c.n_cols = n_cols;
    c.segs = segs;
    c.seg0 = seg0;
    c.rank = rank;
    c.t_stride = t_stride;
    c.c_row = (long long)segs * n_cols;
    c.l_row = block * n_cols;
    c.l_seg = (long long)rows * block * n_cols;
    c.tok_space = 64;
    return c;
}

// fills head/emb/cache/lg with tame or wild patterns; hit rows get their random cached row, miss rows nothing
static void fill(Case& c, std::mt19937_64& rng, bool wild, double hit_rate, double special_rate) {
    std::uniform_real_distribution<double> u(-4.0, 4.0);
    std::uniform_int_distribution<int> hitd(0, 999);
    c.tok.resize(c.rows);
    c.slot.assign((size_t)c.tok_space, -1);
    for (int r = 0; r < c.rows; ++r) {
        c.tok[r] = (long long)(rng() % (uint64_t)c.tok_space);
        if (hitd(rng) < hit_rate * 1000) c.slot[c.tok[r]] = (int)(rng() % 4); // a cached row of 4
    }
    c.cache.assign((size_t)4 * c.c_row, 0);
    for (auto& x : c.cache) x = wild ? (uint16_t)rng() : f16_bits((float)u(rng));
    c.emb.assign((size_t)c.tok_space * c.rank, 0);
    for (auto& x : c.emb) x = wild ? (uint16_t)rng() : b16_bits((float)u(rng));
    c.head.assign((size_t)((long long)(c.seg0 + c.segs) * c.n_cols) * c.rank, 0);
    for (auto& x : c.head) x = wild ? (uint16_t)rng() : f16_bits((float)u(rng));
    c.lg.assign((size_t)(c.segs * c.l_seg), 0.0f);
    for (auto& x : c.lg) x = (float)u(rng);
    // special logits at random columns: NaN, +-inf, -0
    const long long cols = (long long)c.segs * c.n_cols;
    std::uniform_int_distribution<long long> cd(0, cols - 1);
    std::uniform_int_distribution<int> sd(0, 4);
    const int n_special = (int)(special_rate * cols) + 3;
    for (int i = 0; i < n_special; ++i) {
        float v = (float[]){ NAN, INFINITY, -INFINITY, -0.0f, 0.0f }[sd(rng)];
        for (int r = 0; r < c.rows; ++r) {
            long long cc = cd(rng);
            long long s = cc / c.n_cols, col = cc % c.n_cols;
            c.lg[(long long)s * c.l_seg + (long long)r * c.l_row + col] = v;
        }
    }
}

