                            0x1p-24f, -0x1p-24f, 0x1p-25f, 0x1.8p-25f, 0x1p-14f, 0x1p-11f, 1.0f + 0x1p-11f,
                            1.0f + 0x1.8p-11f, 0x1.fffffep15f, 0x1.002p16f, INFINITY, -INFINITY, NAN, -NAN,
