        Case c = make_case(rows, 3000, 1, 2, 33, 1, 6);
        fill(c, rng, false, 0.5, 0.002);
        run_case("mixed-hit-miss", c);
        Case h = make_case(rows, 1500, 1, 0, 2, 1, 5);
        fill(h, rng, false, 1.0, 0.002);
        run_case("all-hit", h);
