    {
        Case c = make_case(2, 2176, 1, 1, 2, 1, 6); // ids 2176..: three tiles, the last 128 columns
        fill(c, rng, false, 0.0, 0.0);
        // bias 0 everywhere (zero head), set exact ties in the logits
        for (auto& x : c.head) x = 0;
        for (int r = 0; r < 2; ++r)
