                for (long long i = 0; i < (long long)c.segs * c.n_cols; ++i) c.lg[s * c.l_seg + r * c.l_row + i] = -7.0f;
        c.lg[0 * c.l_row + 5] = 3.0f; // row 0 tile 0
        c.lg[0 * c.l_row + 900] = 3.0f; // tie in tile 0 -> id 2181
        c.lg[0 * c.l_row + 1030] = 5.0f; // row 0 tile 1, beats tile 0
        c.lg[0 * c.l_row + 2100] = 5.0f; // tie across tiles 1 and 2 -> the lower id (tile 1's)
        c.lg[1 * c.l_row + 2175] = -7.0f; // row 1: the last valid column ties the -inf... all tie at -7 -> lowest id
        run_case("ties", c);
