        c.lg[1 * c.l_row + 40] = INFINITY;
        c.lg[1 * c.l_row + 90] = INFINITY; // row 1: +inf tie -> id 40
        for (long long i = 0; i <= 1025; ++i) c.lg[2 * c.l_row + i] = -INFINITY; // row 2: every valid column -inf
        run_case("nan-inf", c);
    }

