        Case c = make_case(4, 64640, 1, 1, 256, 1, 6);
        fill(c, rng, false, 0.5, 0.0005);
        run_case("served-shape", c);
    }

    printf("%lld cases, %lld rows compared\n", g_cases, g_rows);
    if (g_fail) {
        printf("%d FAILURES\n", g_fail);
        return 1;
    }
    printf("all match\n");
    return 0;
}

