static uint16_t ref_f16(float x) {
    if (std::isnan(x)) return 0x7e00u;
    const uint16_t sgn = std::signbit(x) ? 0x8000u : 0u;
    const double a = std::fabs((double)x);
    if (a == 0.0) return sgn;
    int e = 0;
    (void)std::frexp(a, &e);           // a = m * 2^e, m in [0.5, 1)
    int exp = e - 1;                   // a = 1.f * 2^exp
    if (exp > 15) return sgn | 0x7c00u;
    int frac_bits = 10;
    if (exp < -14) frac_bits = 10 + (exp + 14);
    if (frac_bits < 0) {
