        return (a > 0x1p-25) ? sgn | 1u : sgn;
    }
    double scaled = std::ldexp(a, frac_bits + 1);   // in half-step units of the kept field
    double q = std::nearbyint(scaled);              // nearest, ties to even (FE_TONEAREST)
    long long v = (long long)q;
    int exp2 = exp;
    if (v >= (1LL << (frac_bits + 1))) { v >>= 1; exp2 += 1; }   // the rounding overflowed the significand
    if (exp2 > 15) return sgn | 0x7c00u;
    unsigned frac = (unsigned)v & ((1u << frac_bits) - 1);
    if (exp2 < -14) return sgn | frac;
    return sgn | (unsigned)((exp2 + 15) << 10) | frac;
}
