// Throwaway diagnostic (NOT the deliverable — h0267/ holds that): the fused kernel's exact source vs an independent
// reference, to settle whether the h0267 matrix failures are kernel bugs or harness bugs. My reference is written
// from the kit spec: bias -> fp16 round (nearest even) -> + logit -> tile argmax (NaN above everything, ties to the
// lower index). Compiled -ffp-contract=off; x86-64 SSE single precision.
#include <algorithm>
#include <cfloat>
#include <cmath>
#include <condition_variable>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fenv.h>
#include <mutex>
#include <thread>
#include <vector>

#define __global__
#define __device__
#define __shared__
#define __forceinline__ inline
#define __launch_bounds__(...)
#define __restrict__ __restrict__

struct dim3 { unsigned x, y, z; };
thread_local dim3 threadIdx, blockIdx, gridDim, blockDim;

struct Barrier {
    std::mutex m;
    std::condition_variable cv;
    int count = 0, generation = 0;
    void arrive(int n) {
        asm volatile("" ::: "memory");
        std::unique_lock lk(m);
        int g = generation;
        if (++count == n) { count = 0; ++generation; lk.unlock(); cv.notify_all(); asm volatile("" ::: "memory"); return; }
        cv.wait(lk, [&] { return generation != g; });
        asm volatile("" ::: "memory");
    }
};
struct SimBlock {
    float sv[256];
    int si[256];
    Barrier bar;
    void clear_shm() { std::memset(sv, 0, sizeof sv); std::memset(si, 0, sizeof si); }
};
