// ---- the independent reference (frexp/nearbyint rounding; ref rule written from the spec wording) --------------
static uint16_t ref_f16(float x) {
    const uint16_t sgn = std::signbit(x) ? 0x8000u : 0u;
    if (std::isnan(x)) return (uint16_t)(sgn | 0x7e00u);
    if (std::isinf(x)) return (uint16_t)(sgn | 0x7c00u);
    const double a = std::fabs((double)x);
    if (a == 0.0) return sgn;
    int e; (void)std::frexp(a, &e);
    int exp = e - 1, frac_bits = 10;
    if (exp < -14) frac_bits = 10 + (exp + 14);
    if (frac_bits < 0) return (a > 0x1p-25) ? (uint16_t)(sgn | 1u) : sgn;
    long long v = (long long)std::nearbyint(std::ldexp(a, frac_bits + 1));
    if (v >= (1LL << (frac_bits + 1))) { v >>= 1; ++exp; }
    if (exp > 15) return (uint16_t)(sgn | 0x7c00u);
    unsigned frac = (unsigned)v & ((1u << frac_bits) - 1);
    if (exp < -14) return (uint16_t)(sgn | frac);
    return (uint16_t)(sgn | ((unsigned)(exp + 15) << 10) | frac);
}
static bool ref_better(float a, int ia, float b, int ib) {
    bool na = a != a, nb = b != b;
    if (na != nb) return na;
    if (na) return ia < ib;
    if (a != b) return a > b;
    return ia < ib;
}

static uint64_t g_seed = 987654321;
static uint64_t rnd() { g_seed = g_seed * 6364136223846793005ULL + 1442695040888963407ULL; return g_seed >> 17; }

struct Case {
    int n_rows, cols, segs, seg0, rank, t_stride, l_row, l_seg, n_part, c_row, slot_rows;
    std::vector<float> lg;
    std::vector<int64_t> tok;
    std::vector<int32_t> slot;
    std::vector<uint16_t> cache, emb, head;

    void build(int rows, int cols_, int segs_, int seg0_, int rank_, bool pad) {
        n_rows = rows; cols = cols_; segs = segs_; seg0 = seg0_; rank = rank_;
        t_stride = pad ? 3 : 1;
        n_part = ((cols + 1023) / 1024) * segs;
        c_row = segs * cols;
        l_row = cols + (pad ? 5 : 0);
        l_seg = n_rows * l_row + (pad ? 7 : 0);
        lg.assign((size_t)segs * l_seg + (size_t)n_rows * l_row + cols, 0.0f);
        tok.assign((size_t)t_stride * n_rows, 0);
        slot.assign(rows + 1, -1);
        emb.assign((size_t)(rows + 1) * rank, 0);
        head.assign((size_t)(seg0 + segs) * (size_t)cols * rank, 0);
        cache.clear();
    }
    // rows 0..hits-1 cached (row 0 at slot 0 when pin0); the rest miss
    void tokens(int hits, bool pin0) {
        for (int r = 0; r < n_rows; ++r) tok[(size_t)r * t_stride] = r;
        std::fill(slot.begin(), slot.end(), -1);
        if (hits > 0) {
            cache.assign((size_t)hits * c_row, 0);
            if (pin0) { slot[0] = 0; }
            int w = 0;
            for (int r = 0; r < hits && r < n_rows; ++r) {
                if (pin0 && r == 0) { ++w; continue; }
                slot[r] = w++;
            }
        }
    }
};

static void fill_pool(Case& c, bool specials) {
    static const float pool[] = { 0.0f, 1.0f, -1.0f, 2.0f, 0.5f, -0.0f };
    static const float spool[] = { 0.0f, 1.0f, INFINITY, -INFINITY, 1e30f, -3.0f };
    for (int r = 0; r < c.n_rows; ++r)
        for (int j = 0; j < c.cols; ++j) {
            float v = specials ? spool[(r * 7 + j * 13) % 6] : pool[(r * 5 + j * 11) % 6];
            if (specials && (r * 17 + j) % 23 == 0) { unsigned nb = 0x7fc00000u + (unsigned)(j & 7); memcpy(&v, &nb, 4); }
            for (int s = 0; s < c.segs; ++s) c.lg[(size_t)s * c.l_seg + (size_t)r * c.l_row + j] = v;
        }
    static const uint16_t hp[] = { 0x3C00, 0x3800, 0x4000, 0x3400, 0x0000, 0xBC00 }; // fp16 1,.5,2,.25,0,-1
    for (size_t i = 0; i < c.cache.size(); ++i) c.cache[i] = hp[(i * 3) % 6];
    for (size_t i = 0; i < c.emb.size(); ++i) c.emb[i] = (i % 6 == 5) ? 0xBF00 : hp[(i * 7) % 5]; // bf16 halves-ish
    for (size_t i = 0; i < c.head.size(); ++i) c.head[i] = hp[(i * 5) % 6];
}

// finite wild weights + wild logits (the brief's specials are NaN/inf LOGITS; weights stay finite)
static void fill_wild(Case& c, bool wild_logits) {
    for (size_t i = 0; i < c.lg.size(); ++i) {
        if (wild_logits) {
            unsigned b = (unsigned)rnd() | (((unsigned)rnd() & 0xff) << 16);
            memcpy(&c.lg[i], &b, 4);
        } else {
            c.lg[i] = (float)((int)(rnd() % 21) - 10) * 0.25f;
        }
    }
    for (size_t i = 0; i < c.cache.size(); ++i) c.cache[i] = (uint16_t)(rnd() & 0x7bff); // finite fp16
    for (size_t i = 0; i < c.emb.size(); ++i) c.emb[i] = (uint16_t)(rnd() & 0x7f7f); // finite bf16
    for (size_t i = 0; i < c.head.size(); ++i) c.head[i] = (uint16_t)(rnd() & 0x7bff); // finite fp16
}

static void ref_step(const Case& c, std::vector<float>& pv, std::vector<int32_t>& pi, std::vector<int64_t>& ids) {
    const int s_tiles = (c.cols + 1023) / 1024;
    pv.assign((size_t)c.n_rows * c.n_part, 0.0f);
    pi.assign((size_t)c.n_rows * c.n_part, 0);
    ids.assign(c.n_rows, -1);
    std::vector<float> efp(c.rank);
    for (int r = 0; r < c.n_rows; ++r) {
        const int64_t t = c.tok[(size_t)r * c.t_stride];
        const int at = c.slot[(size_t)t];
        for (int k = 0; k < c.rank; ++k) efp[k] = __half2float({ ref_f16(__bfloat162float({ c.emb[(size_t)t * c.rank + k] })) });
        for (int s = 0; s < c.segs; ++s) {
            for (int ti = 0; ti < s_tiles; ++ti) {
                float bv = -INFINITY; int bi = 1 << 30;
                for (int j = ti * 1024; j < (ti + 1) * 1024 && j < c.cols; ++j) {
                    float b;
                    if (at >= 0) b = __half2float({ c.cache[(size_t)at * c.c_row + (size_t)s * c.cols + j] });
                    else {
                        float acc = 0.0f;
                        const uint16_t* h = &c.head[((size_t)(c.seg0 + s) * c.cols + j) * c.rank];
                        for (int k = 0; k < c.rank; ++k) acc = acc + __half2float({ h[k] }) * efp[k];
                        b = __half2float({ ref_f16(acc) });
                    }
                    float sc = c.lg[(size_t)s * c.l_seg + (size_t)r * c.l_row + j] + b;
                    int v = (c.seg0 + s) * c.cols + j;
                    if (ref_better(sc, v, bv, bi)) { bv = sc; bi = v; }
                }
                pv[(size_t)r * c.n_part + s * s_tiles + ti] = bv;
                pi[(size_t)r * c.n_part + s * s_tiles + ti] = bi;
            }
        }
        float bv = -INFINITY; int bi = 1 << 30;
        for (int p = c.n_part - 1; p >= 0; --p) // reverse fold: the total order must agree
            if (ref_better(pv[(size_t)r * c.n_part + p], pi[(size_t)r * c.n_part + p], bv, bi)) {
                bv = pv[(size_t)r * c.n_part + p]; bi = pi[(size_t)r * c.n_part + p];
            }
        ids[r] = bi;
    }
}

static void run_kernel(Case& c, std::vector<float>& pv, std::vector<int32_t>& pi, std::vector<int64_t>& ids) {
    const int s_tiles = (c.cols + 1023) / 1024;
    pv.assign((size_t)c.n_rows * c.n_part, 0.0f);
    pi.assign((size_t)c.n_rows * c.n_part, 0);
    for (int by = 0; by < c.segs; ++by) for (int bx = 0; bx < s_tiles; ++bx) {
        SimBlock b;
        b.clear_shm();
        std::vector<std::thread> ts;
        for (int t = 0; t < 256; ++t) ts.emplace_back([&, t, bx, by]() {
            blk = &b;
            threadIdx = { (unsigned)t, 0, 0 };
            blockIdx = { (unsigned)bx, (unsigned)by, 0 };
            gridDim = { (unsigned)s_tiles, (unsigned)c.segs, 0 };
            blockDim = { 256, 0, 0 };
            tf_ds_markov_fused_kernel(c.lg.data(), (uint64_t)c.l_seg, (uint64_t)c.l_row, c.tok.data(),
                (uint64_t)c.t_stride, c.slot.data(), (const __half*)c.cache.data(), (uint64_t)c.c_row,
                (const __nv_bfloat16*)c.emb.data(), (const __half*)c.head.data(), c.rank, pv.data(), pi.data(),
                c.n_rows, c.cols, c.seg0, c.n_part, 0);
        });
        for (auto& th : ts) th.join();
    }
    ids.assign(c.n_rows, -1);
    for (int r = 0; r < c.n_rows; ++r) {
        float bv = -INFINITY; int bi = 1 << 30;
        for (int p = 0; p < c.n_part; ++p)
            if (tf_ds_markov_better(pv[(size_t)r * c.n_part + p], pi[(size_t)r * c.n_part + p], bv, bi)) {
                bv = pv[(size_t)r * c.n_part + p]; bi = pi[(size_t)r * c.n_part + p];
            }
        ids[r] = bi;
    }
}

static int g_cases = 0, g_fail = 0;
static bool same_bits(float a, float b) { uint32_t x, y; memcpy(&x, &a, 4); memcpy(&y, &b, 4); return x == y; }

static void check(const char* name, Case& c) {
    std::vector<float> kpv, rpv; std::vector<int32_t> kpi, rpi; std::vector<int64_t> kids, rids;
    run_kernel(c, kpv, kpi, kids);
    ref_step(c, rpv, rpi, rids);
    ++g_cases;
    bool ok = true;
    for (size_t i = 0; i < kpv.size(); ++i) if (!same_bits(kpv[i], rpv[i]) || kpi[i] != rpi[i]) ok = false;
    for (int r = 0; r < c.n_rows; ++r) if (kids[r] != rids[r]) ok = false;
    if (!ok) {
        ++g_fail;
        printf("FAIL %s: rows=%d cols=%d segs=%d seg0=%d rank=%d\n", name, c.n_rows, c.cols, c.segs, c.seg0, c.rank);
        for (int r = 0; r < c.n_rows; ++r) for (int p = 0; p < c.n_part; ++p) {
            size_t i = (size_t)r * c.n_part + p;
            if (!same_bits(kpv[i], rpv[i]) || kpi[i] != rpi[i])
                printf("  row %d tile %d: kernel (%g, %d / %08x) ref (%g, %d / %08x)\n", r, p, kpv[i], kpi[i],
