        check("wild-simple-lg", c);
    }
    for (int n = 0; n < 60; ++n) {
        Case c;
        c.build(1 + (int)(rnd() % 4), 1 + (int)(rnd() % 3000), 1 + (int)(rnd() % 2), (int)(rnd() % 4), 1 + (int)(rnd() % 24), (rnd() & 1) != 0);
        c.tokens((int)(rnd() % 4), (rnd() & 1) != 0);
        fill_wild(c, true);
        check("wild-lg", c);
    }
